import json
def solve(t):
    pts=[(r,c) for r,row in enumerate(t) for c,x in enumerate(row) if x!=0]
    rs=[r for r,_ in pts]; cs=[c for _,c in pts]
    r1,r2,c1,c2=min(rs),max(rs),min(cs),max(cs)
    out=[row[:] for row in t]
    for r in range(r1,r2+1):
        for c in (c1,c2):
            if out[r][c]==0: out[r][c]=t[r][c1] if False else 8
    for c in range(c1,c2+1):
        for r in (r1,r2):
            if out[r][c]==0: out[r][c]=8
    return out
